package delimited

import (
	"bytes"
	"encoding/binary"
	"unicode/utf16"
)

// The byte order marks a file may open with to say outright what it is written
// in. None of them is valid UTF-8 text on its own, so a file that starts with
// one is telling us its encoding rather than holding those bytes by accident.
var (
	utf8BOM    = []byte{0xEF, 0xBB, 0xBF}
	utf16LEBOM = []byte{0xFF, 0xFE}
	utf16BEBOM = []byte{0xFE, 0xFF}
	utf32LEBOM = []byte{0xFF, 0xFE, 0x00, 0x00}
)

// ToUTF8 reads a body as the encoding it announces and hands back UTF-8 text
// with the announcement removed. A file that announces nothing is handed back
// untouched, for the caller to accept or refuse — without a mark there is no
// telling UTF-16 from a file that happens to hold those bytes, and this rule
// guesses at nothing.
//
// Windows tools write UTF-16 far more often than anyone expects: Windows
// PowerShell's Export-Csv and Out-File default to UTF-16LE with a mark, and
// Excel's "유니코드 텍스트" save does the same. Such a file is not broken and
// not ambiguous — it says on its first two bytes what it is — but read as
// UTF-8 it is not text at all, so the importer used to refuse the whole
// upload with "CSV must be UTF-8 encoded" and leave no way out.
func ToUTF8(data []byte) []byte {
	switch {
	case bytes.HasPrefix(data, utf8BOM):
		return data[len(utf8BOM):]
	case bytes.HasPrefix(data, utf32LEBOM):
		// UTF-32LE opens with the UTF-16LE mark and two zero bytes. Reading it
		// as UTF-16 would make garbage out of a file we simply cannot read, so
		// leave it alone and let the caller refuse it.
		return data
	case bytes.HasPrefix(data, utf16LEBOM):
		return fromUTF16(data[len(utf16LEBOM):], binary.LittleEndian)
	case bytes.HasPrefix(data, utf16BEBOM):
		return fromUTF16(data[len(utf16BEBOM):], binary.BigEndian)
	}
	return data
}

// fromUTF16 turns pairs of bytes into UTF-8 text. A lone byte at the end is a
// half-written character and is dropped; a lone surrogate becomes U+FFFD, the
// character that stands for "unreadable here", so one bad pair costs its own
// character and not the file.
func fromUTF16(data []byte, order binary.ByteOrder) []byte {
	units := make([]uint16, 0, len(data)/2)
	for index := 0; index+1 < len(data); index += 2 {
		units = append(units, order.Uint16(data[index:index+2]))
	}
	return []byte(string(utf16.Decode(units)))
}
// Package delimited holds the rules that decide how a delimited file is read:
// which encoding it is written in and what cuts it into columns. Two doors
// lead in — the importer that takes an uploaded CSV and IMPORTDATA that takes
// one over https — and the same file has to be read the same way whichever
// door it comes in by.
package delimited

import "strings"

// separators are what a CSV in the wild is cut by, comma first so a file that
// no candidate cuts more evenly than another stays a comma file.
var separators = []rune{',', ';', '\t'}

// maxSampledLines bounds how far into the body the rule reads. Ten lines is
// enough for a title or a blank line at the top to be outvoted by the rows
// under it, and it keeps the rule from walking a twenty-megabyte body.
const maxSampledLines = 10

// Delimiter answers which separator cuts the body into columns: whichever cuts
// the most of the first few lines into one and the same number of columns,
// comma when none of them does or when two do equally well.
//
// Excel on a locale whose decimal mark is a comma writes and expects
// semicolons, so a file exported there arrives as one column per row unless
// ';' is counted too — a whole sheet in column A, with =SUM over it adding
// nothing up. Reading past the first line is what makes that hold for the
// files reporting tools actually write: a report title or a blank line above
// the header cuts into nothing at all, and letting that one line decide put
// the same whole sheet back into column A.
func Delimiter(body string) rune {
	lines := headLines(body)
	best, bestAgreeing := ',', -1
	for _, separator := range separators {
		if agreeing := agreement(lines, byte(separator)); agreeing > bestAgreeing {
			best, bestAgreeing = separator, agreeing
		}
	}
	return best
}

// headLines takes the first few lines without copying the rest of the body.
func headLines(body string) []string {
	lines := make([]string, 0, maxSampledLines)
	for len(lines) < maxSampledLines && body != "" {
		line, rest, _ := strings.Cut(body, "\n")
		lines, body = append(lines, line), rest
	}
	return lines
}

// agreement counts the lines a separator cuts into one and the same number of
// columns — the most any single column count musters. A line it does not cut at
// all says nothing about it and is left out, which is what lets the rows under
// a one-cell title outvote the title.
func agreement(lines []string, separator byte) int {
	linesWith := make(map[int]int, len(lines))
	best := 0
	for _, line := range lines {
		count := countOutsideQuotes(line, separator)
		if count == 0 {
			continue
		}
		linesWith[count]++
		if linesWith[count] > best {
			best = linesWith[count]
		}
	}
	return best
}

// countOutsideQuotes counts a separator only where it separates. A quoted
// field may hold any of the candidates as ordinary text — `이름,"가,나;다;라"`
// is two columns cut by a comma, not four cut by a semicolon — and counting
// what is inside the quotes would pick the wrong separator for the whole file.
// Each line is read on its own, so an unbalanced quote loses only the line it
// is on rather than everything under it; a file that is nothing but such lines
// counts nothing and so falls back to comma.
func countOutsideQuotes(line string, separator byte) int {
	count, quoted := 0, false
	for index := 0; index < len(line); index++ {
		switch {
		case line[index] == '"':
			quoted = !quoted
		case !quoted && line[index] == separator:
			count++
		}
	}
	return count
}

// Package external fetches what WEBSERVICE and IMPORTDATA ask for, under the
// administrator's policy. It is off until switched on, reaches only hosts on
// the allow-list over https, refuses private and link-local addresses even when
// DNS points a permitted name at them, follows no redirects, and stops reading
// at a size ceiling. A spreadsheet that can call out is a spreadsheet that can
// be pointed at the metadata service or the database next door; the policy is
// what makes the function safe to hand to every user.
package external

import (
	"context"
	"encoding/csv"
	"errors"
	"fmt"
	"io"
	"log/slog"
	"net"
	"net/http"
	"net/url"
	"strings"
	"sync"
	"time"
	"unicode/utf8"

	"kanpic/internal/delimited"
	"kanpic/internal/formula"
)

type settingsProvider interface {
	Values(context.Context) (map[string]any, error)
}

// Config is the administrator's policy, read from settings on every fetch so a
// change takes effect without a restart.
type Config struct {
	Enabled      bool
	AllowedHosts []string
	Timeout      time.Duration
	MaxBytes     int64
	CacheFor     time.Duration
}

const (
	defaultTimeout  = 10 * time.Second
	defaultMaxBytes = 1 << 20 // 1 MiB
	defaultCacheFor = 5 * time.Minute
	// failureCacheFor caps how long a failure that came from the far side is
	// kept. Whether the answer is right is the remote's business, not the
	// policy's: a 503 during a deploy or one call that ran out of time must not
	// go on being the answer for cache_seconds (up to a day) after the remote is
	// well again. Keeping it for a little while all the same is what stops a
	// workbook from paying the timeout afresh on every recalculation.
	failureCacheFor = 30 * time.Second
	// MaxRequestsPerRecalculation bounds one recalculation's outbound calls.
	MaxRequestsPerRecalculation = 20
	maxCSVCells                 = formula.MaxImportedCells
	// maxCacheEntries bounds the answer cache. Nothing but a new answer ever
	// touches the map, so without a ceiling a workbook that fetches a fresh
	// address on every recalculation would grow it until the process died.
	maxCacheEntries = 512
	// maxMessageRunes trims a foreign error before it goes in a cell.
	maxMessageRunes = 160
)

type cached struct {
	result  formula.ExternalResult
	expires time.Time
}

// Fetcher resolves external requests. It is safe for concurrent use.
type Fetcher struct {
	settings settingsProvider
	logger   *slog.Logger
	now      func() time.Time
	// allowPrivate lets tests reach an httptest server on the loopback
	// interface. Production never sets it.
	allowPrivate bool
	// tlsClient lets tests trust an httptest certificate. Production leaves it
	// nil and builds a client under the policy above.
	tlsClient *http.Client
	mu        sync.Mutex
	cache     map[string]cached
}

func New(settings settingsProvider, logger *slog.Logger) *Fetcher {
	if logger == nil {
		logger = slog.Default()
	}
	return &Fetcher{settings: settings, logger: logger, now: func() time.Time { return time.Now() }, cache: make(map[string]cached)}
}

func (f *Fetcher) config(ctx context.Context) (Config, error) {
	config := Config{Timeout: defaultTimeout, MaxBytes: defaultMaxBytes, CacheFor: defaultCacheFor}
	if f.settings == nil {
		return config, nil
	}
	values, err := f.settings.Values(ctx)
	if err != nil {
		return config, err
	}
	if enabled, ok := values["external.enabled"].(bool); ok {
		config.Enabled = enabled
	}
	config.AllowedHosts = stringList(values["external.allowed_hosts"])
	config.Timeout = time.Duration(bounded(values["external.timeout_seconds"], int(defaultTimeout/time.Second), 1, 120)) * time.Second
	config.MaxBytes = int64(bounded(values["external.max_kb"], defaultMaxBytes/1024, 1, 20*1024)) * 1024
	config.CacheFor = time.Duration(bounded(values["external.cache_seconds"], int(defaultCacheFor/time.Second), 0, 86_400)) * time.Second
	return config, nil
}

// Resolve answers every request, never returning fewer entries than it was
// asked for: a request that is refused comes back with the reason attached.
func (f *Fetcher) Resolve(ctx context.Context, requests []formula.ExternalRequest) map[string]formula.ExternalResult {
	if len(requests) == 0 {
		return nil
	}
	results := make(map[string]formula.ExternalResult, len(requests))
	fail := func(request formula.ExternalRequest, code, message string) {
		results[formula.ExternalKey(request.Function, request.URL)] = formula.ExternalResult{Err: &formula.Error{Code: code, Message: message}}
	}
	config, err := f.config(ctx)
	if err != nil {
		for _, request := range requests {
			fail(request, "#N/A", "외부 호출 설정을 읽지 못했습니다")
		}
		return results
	}
	if !config.Enabled {
		for _, request := range requests {
			fail(request, "#N/A", "외부 호출이 꺼져 있습니다. 관리자가 external.enabled 를 켜야 합니다")
		}
		return results
	}
	if len(requests) > MaxRequestsPerRecalculation {
		for _, request := range requests {
			fail(request, "#N/A", fmt.Sprintf("한 번에 외부 호출은 %d개까지입니다", MaxRequestsPerRecalculation))
		}
		return results
	}
	for _, request := range requests {
		key := formula.ExternalKey(request.Function, request.URL)
		if _, done := results[key]; done {
			continue
		}
		results[key] = f.one(ctx, config, request)
	}
	return results
}

func (f *Fetcher) one(ctx context.Context, config Config, request formula.ExternalRequest) formula.ExternalResult {
	// The policy check reads the administrator's settings and reaches nothing,
	// so it stands outside the cache in both directions: a refusal is not kept,
	// and an answer kept earlier is not handed back once the address has left
	// the allow-list. Otherwise a fixed allowed_hosts would take up to
	// cache_seconds to be believed.
	target, err := CheckURL(request.URL, config.AllowedHosts)
	if err != nil {
		return formula.ExternalResult{Err: &formula.Error{Code: "#N/A", Message: err.Error()}}
	}
	key := cacheKey(config, request)
	f.mu.Lock()
	if hit, ok := f.cache[key]; ok && f.now().Before(hit.expires) {
		f.mu.Unlock()
		return hit.result
	}
	f.mu.Unlock()
	body, err := f.fetch(ctx, config, target)
	var result formula.ExternalResult
	keepFor := config.CacheFor
	if err != nil {
		result = formula.ExternalResult{Err: &formula.Error{Code: "#N/A", Message: err.Error()}}
		var fromTheFarSide remoteFailure
		if errors.As(err, &fromTheFarSide) && keepFor > failureCacheFor {
			keepFor = failureCacheFor
		}
	} else if request.Function == "IMPORTDATA" {
		result = parseCSV(body)
	} else {
		result = formula.ExternalResult{Text: body}
	}
	if keepFor > 0 {
		f.store(key, result, f.now().Add(keepFor))
	}
	return result
}

// remoteFailure marks a refusal the remote is responsible for — it answered
// with an error status, or it did not answer at all — as against one this
// policy decided (a redirect, a private address, a body over the ceiling),
// which the same request would earn again from the same response. Only the
// first kind stops being true when somebody else fixes something.
type remoteFailure struct{ err error }

func (r remoteFailure) Error() string { return r.err.Error() }

func (r remoteFailure) Unwrap() error { return r.err }

// cacheKey names an answer by what was asked for and by the policy that shaped
// the asking. The size ceiling and the timeout decide whether a fetch comes
// back with a body or with a refusal, so what was kept under the old ceiling is
// not an answer to the new one: raising external.max_kb has to be believed at
// once, exactly as fixing external.allowed_hosts is. Without this the cell that
// says "응답이 허용된 크기를 넘습니다" goes on saying it for cache_seconds after
// the administrator has already raised the limit, and the administrator sees no
// reason to believe the setting worked.
func cacheKey(config Config, request formula.ExternalRequest) string {
	return fmt.Sprintf("%d\x00%d\x00%s", config.MaxBytes, config.Timeout, formula.ExternalKey(request.Function, request.URL))
}

// store keeps one answer and takes out the rubbish while it is holding the
// lock: expired entries first, and if the map is still full, whichever live
// entry expires soonest.
func (f *Fetcher) store(key string, result formula.ExternalResult, expires time.Time) {
	f.mu.Lock()
	defer f.mu.Unlock()
	if _, replacing := f.cache[key]; !replacing && len(f.cache) >= maxCacheEntries {
		now := f.now()
		for existing, entry := range f.cache {
			if !now.Before(entry.expires) {
				delete(f.cache, existing)
	}
	columns := 0
	for _, record := range records {
		if len(record) > columns {
			columns = len(record)
		}
	}
	if len(records) == 0 || columns == 0 {
		return formula.ExternalResult{}
	}
	if len(records)*columns > maxCSVCells {
		return formula.ExternalResult{Err: &formula.Error{Code: "#NUM!", Message: fmt.Sprintf("IMPORTDATA 는 최대 %d칸까지 가져옵니다", maxCSVCells)}}
	}
	values := make([]any, 0, len(records)*columns)
	for _, record := range records {
		for column := 0; column < columns; column++ {
			if column >= len(record) {
				values = append(values, nil)
				continue
			}
			// 불리언은 원문으로 판정해 공백이 붙은 글자를 그대로 지킨다.
			if boolean, ok := delimited.Boolean(record[column]); ok {
				values = append(values, boolean)
				continue
			}
			// 수로 읽는 자는 업로드 가져오기와 같은 것 하나뿐이다 — 스프레드시트가
			// 수라고 부르는 것이지 Go 가 수라고 부르는 것이 아니다. 16진수도,
			// NaN 도, 밑줄로 자리를 가른 것도 수가 아니고, 우편번호의 "00123"
			// 과 스무 자리 계좌번호는 수로 담으면 적힌 것과 달라지므로 글자다.
			text := strings.TrimSpace(record[column])
			if number, ok := delimited.Number(text); ok {
				values = append(values, number)
			} else {
				values = append(values, record[column])
			}
		}
	}
	return formula.ExternalResult{Rows: len(records), Columns: columns, Values: values}
}

func stringList(value any) []string {
	switch typed := value.(type) {
	case []string:
		return typed
	case []any:
		out := make([]string, 0, len(typed))
		for _, item := range typed {
			if text, ok := item.(string); ok {
				out = append(out, text)
			}
		}
		return out
	case string:
		return strings.Split(typed, ",")
	}
	return nil
}

func bounded(value any, fallback, minimum, maximum int) int {
	number := fallback
	switch typed := value.(type) {
	case float64:
		number = int(typed)
	case int:
		number = typed
	}
	if number < minimum {
		return minimum
	}
	if number > maximum {
		return maximum
	}
	return number
}

// short trims a message that came from elsewhere. It counts letters, not
// bytes, so a Korean message comes back whole instead of ending in a half
// letter the terminal draws as a question mark.
func short(text string) string {
	if utf8.RuneCountInString(text) <= maxMessageRunes {
		return text
	}
	counted := 0
	for index := range text {
		if counted == maxMessageRunes {
			return text[:index] + "…"
		}
		counted++
	}
	return text
}
